content:
{
  "root_cause": "The datepicker component traps focus inside the calendar popup when shown, preventing the Tab key from moving focus to the next form field. This occurs because the Vanilla Calendar Pro library's focus trapping is enabled by default in the calendar options.",
  "repair_strategy": "Disable focus trapping in the Vanilla Calendar Pro instance by setting the `trapFocus` option to false in the calendar options passed to the Calendar constructor.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    const calendarOptions: Options = {
      ...this._config.vcpOptions,
      // Vanilla Calendar Pro v3.4+ ships optional features as extensions. Bootstrap
      // supports only `months`, which `displayMonthsCount` needs.
      extensions: [months],
      inputMode: !this._isInline,
      positionToInput: this._config.placement,
      firstWeekday: this._config.firstWeekday,
      locale: this._config.locale,
      selectionDatesMode: this._config.selectionMode,
      selectedDates: this._config.selectedDates,
      displayMonthsCount: this._config.displayMonthsCount,
      type: this._config.displayMonthsCount > 1 ? 'multiple' : 'default',
      selectedTheme: vcpTheme,
      themeAttrDetect: '[data-bs-theme]',
      onClickDate: (self, event) => this._handleDateClick(self, event),
      onInit: self => {
        this._syncThemeAttribute(self.context.mainElement)
      },
      onShow: () => {
        if (!this._calendar) {
          return
        }

        this._isShown = true
        this._syncThemeAttribute(this._calendar.context.mainElement)
      },
      onHide: () => {
        this._isShown = false
      }
    }",
      "after": "    const calendarOptions: Options = {
      ...this._config.vcpOptions,
      // Vanilla Calendar Pro v3.4+ ships optional features as extensions. Bootstrap
      // supports only `months`, which `displayMonthsCount` needs.
      extensions: [months],
      inputMode: !this._isInline,
      positionToInput: this._config.placement,
      firstWeekday: this._config.firstWeekday,
      locale: this._config.locale,
      selectionDatesMode: this._config.selectionMode,
      selectedDates: this._config.selectedDates,
      displayMonthsCount: this._config.displayMonthsCount,
      type: this._config.displayMonthsCount > 1 ? 'multiple' : 'default',
      selectedTheme: vcpTheme,
      themeAttrDetect: '[data-bs-theme]',
      trapFocus: false,
      onClickDate: (self, event) => this._handleDateClick(self, event),
      onInit: self => {
        this._syncThemeAttribute(self.context.mainElement)
      },
      onShow: () => {
        if (!this._calendar) {
          return
        }

        this._isShown = true
        this._syncThemeAttribute(this._calendar.context.mainElement)
      },
      onHide: () => {
        this._isShown = false
      }
    }"
    }
  ],
  "expected_accessibility_effect": "Pressing Tab will move focus from the departure date field to the passengers field as expected, allowing seamless keyboard navigation through the form.",
  "functional_risks": [
    "Disabling focus trapping may allow focus to leave the calendar accidentally when it is open, but the datepicker component's outside dismissers (on focusin and pointerdown) will hide the calendar when focus leaves, mitigating this risk.",
    "If the VCP library relies on focus trapping for internal keyboard navigation (e.g., arrow keys within the calendar), this change could disrupt those interactions. However, the datepicker component's primary functionality (date selection via mouse or Enter) should remain unaffected."
  ],
  "verification_requirements": [
    "Verify that pressing Tab from the departure date field moves focus to the passengers field.",
    "Verify that the calendar still functions correctly for date selection via mouse and keyboard (arrow keys, Enter, etc.).",
    "Verify that the calendar hides when clicking outside or pressing Escape (as per the regression guard 'Escape still closes the calendar')."
  ]
}
